SELECT 'INSTANCE',map,parent,script,allowMount FROM instance_template WHERE map IN(1456,1458,1466,1477,1492,1493,1501,1516,1544,1571,1651,1677,1753) ORDER BY map;
SELECT 'ENCOUNTER',entry,difficulty,creditType,creditEntry,lastEncounterDungeon FROM instance_encounters WHERE entry IN(1790,1791,1792,1793,1805,1806,1807,1808,1809,1810,1811,1812,1813,1814,1815,1816,1817,1818,1822,1823,1824,1825,1826,1827,1828,1829,1832,1833,1834,1835,1836,1837,1838,1839,1845,1846,1847,1848,1850,1851,1852,1855,1856,1868,1869,1870,1954,1957,1959,1960,1961,1964,1965,2017,2031,2039,2053,2055,2057,2065,2066,2067,2068) ORDER BY entry,difficulty,creditEntry;
SELECT 'ENTRANCE',dungeonId,position_x,position_y,position_z,orientation FROM lfg_entrances WHERE dungeonId IN(1043,1044,1174,1175,1189,1190,1191,1192,1193,1194,1201,1202,1204,1205,1206,1207,1208,1209,1318,1319,1474,1475,1488,1535) ORDER BY dungeonId;
SELECT 'CREATURE',entry,AIName,ScriptName FROM creature_template WHERE entry IN(SELECT creditEntry FROM instance_encounters WHERE entry IN(1790,1791,1792,1793,1805,1806,1807,1808,1809,1810,1811,1812,1813,1814,1815,1816,1817,1818,1822,1823,1824,1825,1826,1827,1828,1829,1832,1833,1834,1835,1836,1837,1838,1839,1845,1846,1847,1848,1850,1851,1852,1855,1856,1868,1869,1870,1954,1957,1959,1960,1961,1964,1965,2017,2031,2039,2053,2055,2057,2065,2066,2067,2068) AND creditType=0) ORDER BY entry;
